import { Entity, PrimaryGeneratedColumn, Column, ManyToOne } from 'typeorm';
import { Cat } from './cat.entity';

@Entity()
export class Toy {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;

  @ManyToOne(() => Cat, (cat) => cat.toys)
  cat: Cat;
}

