import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Cat } from './cat.entity';
import { CatResponseDto } from './cat-response.dto';

@Injectable()
export class CatsService {
  constructor(
    @InjectRepository(Cat)
    private readonly catRepository: Repository<Cat>,
  ) {}

  async findAll(): Promise<CatResponseDto[]> {
    // 1 query: loads only the root cat rows, no relations hydrated.
    const cats = await this.catRepository.find();

    const result: CatResponseDto[] = [];
    for (const cat of cats) {
      // Lazy relation resolved inside the loop: fires
      // `SELECT * FROM toy WHERE cat_id = ?` once PER cat.
      const toys = await cat.toys;

      result.push({
        id: cat.id,
        name: cat.name,
        breed: cat.breed,
        toyNames: toys.map((toy) => toy.name),
      });
    }

    return result;
  }
}

